import { test, expect } from 'bun:test';
import { createDb } from '../src/db.js';
import { requestReset, confirmReset } from '../src/reset.js';
test('reset changes the password', () => {
  const db = createDb();
  const token = requestReset(db, 'ann@example.test', 1000);
  expect(typeof token).toBe('string');
  confirmReset(db, token, 'new-pass', 2000);
  expect(db.users.get('u1').password).toBe('new-pass');
});
test('unknown email and token throw', () => {
  const db = createDb();
  expect(() => requestReset(db, 'nobody@example.test', 1)).toThrow();
  expect(() => confirmReset(db, 'nope', 'x', 1)).toThrow();
});

