import { test, expect } from 'bun:test';
import { createDb } from '../src/db.js';
import { requestReset, confirmReset } from '../src/reset.js';
const DAY = 24 * 3600 * 1000;
test('a token expires', () => {
  const db = createDb();
  const token = requestReset(db, 'ann@example.test', 1000);
  expect(() => confirmReset(db, token, 'late', 1000 + 2 * DAY)).toThrow();
  expect(db.users.get('u1').password).toBe('old-pass');
});
test('a token works once', () => {
  const db = createDb();
  const token = requestReset(db, 'ann@example.test', 1000);
  confirmReset(db, token, 'first', 2000);
  expect(() => confirmReset(db, token, 'second', 3000)).toThrow();
  expect(db.users.get('u1').password).toBe('first');
});
